-- Enable UUID extension CREATE EXTENSION IF NOT EXISTS 'uuid-ossp'; -- Profiles table CREATE TABLE profiles ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), full_name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT, business_name TEXT, business_address TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() ); -- Customers table CREATE TABLE customers ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), deleted_at TIMESTAMPTZ, created_by UUID REFERENCES profiles(id), total_orders INTEGER DEFAULT 0, outstanding_balance NUMERIC DEFAULT 0, last_visit TIMESTAMPTZ ); CREATE INDEX idx_customers_phone ON customers(phone); CREATE INDEX idx_customers_name ON customers(name); CREATE INDEX idx_customers_deleted_at ON customers(deleted_at); -- Products table CREATE TABLE products ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, category TEXT, sku TEXT UNIQUE, purchase_price NUMERIC DEFAULT 0, selling_price NUMERIC DEFAULT 0, current_stock INTEGER DEFAULT 0, minimum_stock INTEGER DEFAULT 0, location TEXT, remarks TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), deleted_at TIMESTAMPTZ, created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_products_name ON products(name); CREATE INDEX idx_products_sku ON products(sku); CREATE INDEX idx_products_deleted_at ON products(deleted_at); CREATE INDEX idx_products_stock ON products(current_stock); -- Orders table CREATE TABLE orders ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), order_number TEXT UNIQUE NOT NULL, customer_id UUID NOT NULL REFERENCES customers(id), discount NUMERIC DEFAULT 0, tax NUMERIC DEFAULT 0, advance_payment NUMERIC DEFAULT 0, remaining_amount NUMERIC DEFAULT 0, total_amount NUMERIC DEFAULT 0, delivery_date TIMESTAMPTZ, status TEXT DEFAULT 'pending', notes TEXT, attachments TEXT[] DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), deleted_at TIMESTAMPTZ, created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_orders_customer ON orders(customer_id); CREATE INDEX idx_orders_status ON orders(status); CREATE INDEX idx_orders_created_at ON orders(created_at); CREATE INDEX idx_orders_deleted_at ON orders(deleted_at); -- Order items table CREATE TABLE order_items ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 1, price NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL DEFAULT 0 ); CREATE INDEX idx_order_items_order ON order_items(order_id); -- Order status history CREATE TABLE order_status_history ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, status TEXT NOT NULL, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_order_status_history_order ON order_status_history(order_id); -- Payments table CREATE TABLE payments ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id UUID NOT NULL REFERENCES customers(id), order_id UUID REFERENCES orders(id), amount NUMERIC NOT NULL DEFAULT 0, method TEXT DEFAULT 'cash', reference TEXT, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_payments_customer ON payments(customer_id); CREATE INDEX idx_payments_order ON payments(order_id); CREATE INDEX idx_payments_created_at ON payments(created_at); -- Purchases table CREATE TABLE purchases ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), supplier TEXT NOT NULL, invoice_number TEXT, total_cost NUMERIC DEFAULT 0, transport_cost NUMERIC DEFAULT 0, notes TEXT, attachments TEXT[] DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_purchases_supplier ON purchases(supplier); CREATE INDEX idx_purchases_created_at ON purchases(created_at); -- Purchase items table CREATE TABLE purchase_items ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), purchase_id UUID NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 1, cost NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL DEFAULT 0 ); CREATE INDEX idx_purchase_items_purchase ON purchase_items(purchase_id); -- Sales table CREATE TABLE sales ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), customer_id UUID NOT NULL REFERENCES customers(id), total_amount NUMERIC DEFAULT 0, discount NUMERIC DEFAULT 0, payment_amount NUMERIC DEFAULT 0, due_amount NUMERIC DEFAULT 0, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_sales_customer ON sales(customer_id); CREATE INDEX idx_sales_created_at ON sales(created_at); -- Sale items table CREATE TABLE sale_items ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), sale_id UUID NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 1, price NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL DEFAULT 0 ); CREATE INDEX idx_sale_items_sale ON sale_items(sale_id); -- Returns table CREATE TABLE returns ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), type TEXT NOT NULL, reference_id UUID NOT NULL, total_amount NUMERIC DEFAULT 0, reason TEXT, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_returns_type ON returns(type); CREATE INDEX idx_returns_reference ON returns(reference_id); -- Return items table CREATE TABLE return_items ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), return_id UUID NOT NULL REFERENCES returns(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 1, amount NUMERIC NOT NULL DEFAULT 0 ); CREATE INDEX idx_return_items_return ON return_items(return_id); -- Expenses table CREATE TABLE expenses ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), category TEXT NOT NULL, amount NUMERIC NOT NULL DEFAULT 0, description TEXT, date DATE NOT NULL DEFAULT CURRENT_DATE, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_expenses_category ON expenses(category); CREATE INDEX idx_expenses_date ON expenses(date); CREATE INDEX idx_expenses_created_at ON expenses(created_at); -- Service jobs table CREATE TABLE service_jobs ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), job_number TEXT UNIQUE NOT NULL, customer_id UUID NOT NULL REFERENCES customers(id), product_id UUID REFERENCES products(id), serial_number TEXT, problem TEXT, accessories TEXT, engineer TEXT, expected_date TIMESTAMPTZ, status TEXT DEFAULT 'pending', remarks TEXT, attachments TEXT[] DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_service_jobs_customer ON service_jobs(customer_id); CREATE INDEX idx_service_jobs_status ON service_jobs(status); CREATE INDEX idx_service_jobs_engineer ON service_jobs(engineer); -- Service timeline table CREATE TABLE service_timeline ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), service_id UUID NOT NULL REFERENCES service_jobs(id) ON DELETE CASCADE, status TEXT NOT NULL, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_service_timeline_service ON service_timeline(service_id); -- Warranty table CREATE TABLE warranties ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), service_id UUID NOT NULL REFERENCES service_jobs(id) ON DELETE CASCADE, start_date DATE NOT NULL, end_date DATE NOT NULL, service_count INTEGER DEFAULT 0, free_service_count INTEGER DEFAULT 0, amc BOOLEAN DEFAULT FALSE, reminder_date DATE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() ); CREATE INDEX idx_warranties_service ON warranties(service_id); CREATE INDEX idx_warranties_end_date ON warranties(end_date); -- Parcels table CREATE TABLE parcels ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), parcel_number TEXT UNIQUE NOT NULL, bus_name TEXT NOT NULL, driver_name TEXT, driver_phone TEXT, destination TEXT NOT NULL, receiver_name TEXT NOT NULL, receiver_phone TEXT, charges NUMERIC DEFAULT 0, status TEXT DEFAULT 'booked', notes TEXT, attachments TEXT[] DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_parcels_status ON parcels(status); CREATE INDEX idx_parcels_created_at ON parcels(created_at); -- Stock transactions table CREATE TABLE stock_transactions ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), product_id UUID NOT NULL REFERENCES products(id), type TEXT NOT NULL, quantity INTEGER NOT NULL, reference_id UUID NOT NULL, reference_type TEXT NOT NULL, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_stock_transactions_product ON stock_transactions(product_id); CREATE INDEX idx_stock_transactions_type ON stock_transactions(type); CREATE INDEX idx_stock_transactions_reference ON stock_transactions(reference_id); -- Activities table CREATE TABLE activities ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), type TEXT NOT NULL, description TEXT NOT NULL, reference_id UUID, reference_type TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), created_by UUID REFERENCES profiles(id) ); CREATE INDEX idx_activities_created_at ON activities(created_at); CREATE INDEX idx_activities_type ON activities(type); -- Notifications table CREATE TABLE notifications ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, reference_id UUID, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW() ); CREATE INDEX idx_notifications_is_read ON notifications(is_read); CREATE INDEX idx_notifications_created_at ON notifications(created_at); -- Update triggers for updated_at CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$ language 'plpgsql'; CREATE TRIGGER update_customers_updated_at BEFORE UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_products_updated_at BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_orders_updated_at BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_service_jobs_updated_at BEFORE UPDATE ON service_jobs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_warranties_updated_at BEFORE UPDATE ON warranties FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_parcels_updated_at BEFORE UPDATE ON parcels FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); CREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column(); -- Row Level Security (basic setup) ALTER TABLE customers ENABLE ROW LEVEL SECURITY; ALTER TABLE products ENABLE ROW LEVEL SECURITY; ALTER TABLE orders ENABLE ROW LEVEL SECURITY; ALTER TABLE payments ENABLE ROW LEVEL SECURITY; ALTER TABLE purchases ENABLE ROW LEVEL SECURITY; ALTER TABLE sales ENABLE ROW LEVEL SECURITY; ALTER TABLE returns ENABLE ROW LEVEL SECURITY; ALTER TABLE expenses ENABLE ROW LEVEL SECURITY; ALTER TABLE service_jobs ENABLE ROW LEVEL SECURITY; ALTER TABLE parcels ENABLE ROW LEVEL SECURITY; CREATE POLICY allow_all ON customers FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON products FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON orders FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON payments FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON purchases FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON sales FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON returns FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON expenses FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON service_jobs FOR ALL USING (true) WITH CHECK (true); CREATE POLICY allow_all ON parcels FOR ALL USING (true) WITH CHECK (true);